#!/usr/bin/env python3
"""Generate canonical-JSON ground truth for the Node test suite.

    python3 tests/fixtures/canonical-cases.py > tests/fixtures/canonical-cases.json

Emits, for each case, the input value *and* the exact bytes Python's
`json.dumps(..., sort_keys=True, separators=(",", ":"), ensure_ascii=False)`
produces for it. The Node suite reads this file, rebuilds each value with
`JSON.parse`, and asserts its own canonical encoder produces the same bytes. That
keeps the Node tests hermetic — no Python at test time — while still pinning them
to the reference implementation.

Every control character is built with `chr()` rather than written literally: a
literal control byte in a source file is invisible in a diff, and editors, shells
and copy-paste all mangle it. The JSON container escapes them on the way out, so
the fixture stays plain ASCII-safe text.
"""

import json
import sys

CASES = {
    # ── Key ordering ────────────────────────────────────────────────────────
    "flat_sort": {"b": 1, "a": 2},
    "nested_sort": {"z": {"y": 1, "x": 2}, "a": [{"q": 1, "p": 2}]},
    # Fullwidth A (U+FF21, 65313) against an astral emoji (U+1F600, 128512).
    # Sorting by UTF-16 code unit puts the emoji first, because its leading
    # surrogate is 0xD83D (55357); sorting by code point puts it last. This is
    # the one case where JavaScript's default `.sort()` silently disagrees with
    # Python's `sorted()`, and a disagreement here is a signature that fails on
    # genuine data.
    "astral_key_sort": {"Ａ": 1, "\U0001f600": 2},
    "empty_key": {"": "empty key"},
    # ── Non-ASCII stays raw UTF-8 (ensure_ascii=False) ──────────────────────
    "devanagari": {"k": "पैरासिटामोल ५०० मि.ग्रा."},
    "astral_value": {"k": "\U0001f48a astral"},
    # ── Escaping ────────────────────────────────────────────────────────────
    # Short forms for these five C0 controls in both languages.
    "c0_shortforms": {"k": "".join(chr(c) for c in (0x08, 0x09, 0x0A, 0x0C, 0x0D))},
    # Everything else in C0 becomes \u00xx with lowercase hex in both.
    "c0_other": {"k": chr(0x01) + chr(0x1F)},
    # Neither language escapes DEL, C1, U+2028 or U+2029.
    "del_and_c1": {"k": chr(0x7F) + chr(0x85) + chr(0x9F)},
    "line_separators": {"k": chr(0x2028) + chr(0x2029)},
    # Neither escapes the forward slash; both escape quote and backslash.
    "slash_quote_backslash": {"k": 'a/b"c\\d'},
    # ── Numbers and literals ────────────────────────────────────────────────
    "integers": {"k": [1, 2, 3], "n": 0, "neg": -7, "big": 9007199254740991},
    "literals": {"k": True, "f": False, "nil": None},
    # ── Arrays ──────────────────────────────────────────────────────────────
    # Excipient order is part of the signed data, so it must never be sorted.
    "array_order_preserved": {"ex": ["starch", "lactose", "aspartame"]},
}


def main() -> int:
    out = {
        "_comment": (
            "Generated by tests/fixtures/canonical-cases.py. 'canonical_hex' is the "
            "UTF-8 hex of Python's canonical JSON for 'value'. Do not hand-edit."
        ),
        "cases": [],
    }
    for name, value in CASES.items():
        text = json.dumps(
            value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        )
        out["cases"].append(
            {
                "name": name,
                "value": value,
                "canonical_hex": text.encode("utf-8").hex(),
                "byte_length": len(text.encode("utf-8")),
            }
        )
    json.dump(out, sys.stdout, indent=2, ensure_ascii=True)
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
